<script setup lang="ts">
import Icon from './Icon.vue';
import VisualEditor from './VisualEditor.vue';
import CropEditor from './CropEditor.vue';
import{ref,watch,computed,onMounted}from'vue';import{t,bytes}from'./i18n';import{conversionDefaults,compressionDefaults,type EditOperation,type ConversionOptions,type CropRegion}from'../../../packages/contracts';
const props=defineProps<{open:boolean;initial:File[];busy:boolean;defaults?:ConversionOptions;embedded?:boolean;initialKind?:EditOperation['kind'];compression?:ConversionOptions}>();const emit=defineEmits<{close:[];submit:[files:File[],operation:EditOperation]}>();
const dialog=ref<HTMLDialogElement>();const files=ref<File[]>([...props.initial]);const kind=ref<EditOperation['kind']>(props.initialKind??(props.embedded?'trim':'convert'));const editReady=ref(false);const start=ref(0),end=ref(10);
const crop=ref<CropRegion>();
onMounted(()=>{if(props.open&&!props.embedded){reset();dialog.value?.showModal();}});
const editorMode=computed(()=>kind.value==='merge'?'merge':'trim');
const options=ref<ConversionOptions>({...conversionDefaults,...props.defaults});
function reset(){files.value=[...props.initial];editReady.value=false;kind.value=props.initialKind??(props.embedded?'trim':'convert');start.value=0;end.value=10;options.value={...conversionDefaults,...props.defaults};}
watch(files,()=>{editReady.value=false;crop.value=undefined;},{flush:'sync'});
watch(()=>props.initial,value=>{files.value=[...value];kind.value=props.initialKind??kind.value;});watch(()=>props.initialKind,value=>{if(value)kind.value=value;});
watch(()=>props.defaults,value=>{if(props.embedded&&!files.value.length)options.value={...conversionDefaults,...value};});
watch(()=>props.open,open=>{if(open){reset();if(!props.embedded)dialog.value?.showModal();}else if(!props.embedded)dialog.value?.close();},{flush:'post'});
function select(event:Event){const input=event.target as HTMLInputElement;files.value=(kind.value==='merge'?[...files.value,...input.files??[]]:[...input.files??[]]).slice(0,20);input.value='';}
function move(index:number,to:number){const next=[...files.value],item=next.splice(index,1)[0];if(item){next.splice(to,0,item);files.value=next;}}
function submit(){if(props.busy||kind.value==='trim'&&!editReady.value||kind.value==='crop'&&!crop.value||(kind.value==='merge'?files.value.length<2:files.value.length!==1))return;emit('submit',files.value,{kind:kind.value,...(['convert','compress'].includes(kind.value)?{options:kind.value==='compress'?{...compressionDefaults,...props.compression}:{...options.value}}:{}),...(kind.value==='trim'?{start:start.value,end:end.value}:{}),...(kind.value==='crop'?{crop:{...crop.value!}}:{})});}
</script>
<template><component :is="embedded ? 'section' : 'dialog'" :aria-labelledby="embedded ? undefined : 'media-tools-title'" ref="dialog" class="tools-editor" :class="embedded ? 'tools-panel' : 'history-dialog tools-dialog'" @cancel="emit('close')"><form @submit.prevent="submit"><h2 v-if="!embedded" id="media-tools-title">{{ t('mediaTools') }}</h2><nav v-if="embedded" class="tools-modes" :aria-label="t('operation')"><button v-for="op in ['trim','crop','merge','convert','compress']" :key="op" type="button" :aria-pressed="kind === op" @click="kind = op as EditOperation['kind']"><Icon :name="op" />{{ t(op + 'Tool') }}</button></nav><label v-else>{{ t('operation') }}<select v-model="kind" :aria-label="t('operation')"><option v-for="op in ['convert','compress','merge','trim','crop']" :key="op" :value="op">{{ t(op + 'Tool') }}</option></select></label><p>{{ t(kind + 'Hint') }}</p><label class="secondary file-picker">{{ t('chooseVideos') }}<input type="file" accept="video/*,.mkv,.mov,.webm,.ts,.m2ts,.mts,.m4v,.avi,.mpg,.wmv,.flv,.3gp,.ogg" :multiple="kind === 'merge'" :aria-label="t('chooseVideos')" @change="select"></label><CropEditor v-if="files.length === 1 && kind === 'crop'" :file="files[0]!" @change="crop=$event" /><VisualEditor v-else-if="files.length && ['trim','merge'].includes(kind)" :files="files" :mode="editorMode" :start="start" :end="end" @start="start=$event" @end="end=$event" @valid="editReady=$event" @move="move" @remove="index=>files=files.filter((_,i)=>i!==index)" /><ol v-else class="tool-files"><li v-for="(file,index) in files" :key="index"><span dir="auto">{{ file.name }}</span><small>{{ bytes(file.size) }}</small><button v-if="kind === 'merge' && index" type="button" class="text-button" :aria-label="t('moveUp')" @click="move(index,index-1)"><Icon name="up" /></button><button v-if="kind === 'merge' && index < files.length-1" type="button" class="text-button" :aria-label="t('moveDown')" @click="move(index,index+1)"><Icon name="down" /></button></li></ol><p v-if="['convert','compress'].includes(kind)"><a href="#settings" @click="emit('close')">{{ t('processingDefaults') }}</a></p><p>{{ t('conversionRestartHint') }}</p><div class="dialog-actions"><button class="secondary" type="button" @click="embedded ? reset() : emit('close')">{{ t('cancel') }}</button><button class="primary" :disabled="busy || (kind === 'trim' && !editReady) || (kind === 'crop' && !crop) || (kind === 'merge' ? files.length < 2 : files.length !== 1)">{{ t(kind === 'crop' ? 'cropExport' : 'startTool') }}</button></div></form></component></template>
